class Solution {
public:
    std::string discountPrices(std::string sentence, int discount) {
        std::stringstream ss(sentence);
        std::string word, ans;
        double mult = 1.0 - (double)discount / 100.0;
        bool first = true;
        while (ss >> word) {
            if (!first) ans += " ";
            first = false;
            if (word.size() > 1 && word[0] == '$') {
                bool isNum = true;
                for (size_t i = 1; i < word.size(); ++i) {
                    if (!isdigit(word[i])) { isNum = false; break; }
                }
                if (isNum) {
                    long long val = std::stoll(word.substr(1));
                    char buf[64];
                    snprintf(buf, sizeof(buf), "$%.2f", val * mult);
                    ans += buf;
                    continue;
                }
            }
            ans += word;
        }
        return ans;
    }
};

class Solution {
    public String discountPrices(String sentence, int discount) {
        String[] words = sentence.split(" ");
        double mult = 1.0 - (double) discount / 100.0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) sb.append(" ");
            String w = words[i];
            if (w.length() > 1 && w.charAt(0) == '$') {
                boolean isNum = true;
                for (int j = 1; j < w.length(); j++) {
                    if (!Character.isDigit(w.charAt(j))) { isNum = false; break; }
                }
                if (isNum) {
                    long val = Long.parseLong(w.substring(1));
                    sb.append(String.format(java.util.Locale.US, "$%.2f", val * mult));
                    continue;
                }
            }
            sb.append(w);
        }
        return sb.toString();
    }
}

var discountPrices = function(sentence, discount) {
    const words = sentence.split(" ");
    const mult = 1.0 - discount / 100.0;
    const res = words.map(w => {
        if (w.length > 1 && w[0] === "$" && /^\d+$/.test(w.slice(1))) {
            const val = Number(w.slice(1)) * mult;
            return "$" + val.toFixed(2);
        }
        return w;
    });
    return res.join(" ");
};
